  'Expand Sidebar (Ctrl+[)': { om: 'Barruu bal’isi (Ctrl+[)', am: 'የጎን ማውጫውን ዘርጋ (Ctrl+[)', ar: 'توسيع الشريط الجانبي (Ctrl+[)' },
