export const translatePublicCopy = (source: string, language: Language): string => {
  if (language === 'en') return source;
  const exactTranslation = publicCopy[source]?.[language];
  if (exactTranslation) return exactTranslation;

  const dynamicTemplates: Array<[RegExp, (match: RegExpMatchArray) => string]> = [
    [
      /^New Service Request: (.+)$/,
      ([, serviceType]) =>
        language === 'om'
          ? `Gaaffii Tajaajilaa Haaraa: ${serviceType}`
          : language === 'am'
            ? `አዲስ የአገልግሎት ጥያቄ፡ ${serviceType}`
            : `طلب خدمة جديد: ${serviceType}`,
    ],
    [
      /^(\d+) server-assigned permissions$/,
      ([, count]) =>
        language === 'om'
          ? `Hayyama sirnaatiin kenname ${count}`
          : language === 'am'
            ? `${count} በሰርቨር የተመደቡ ፈቃዶች`
            : `${count} صلاحية محددة من الخادم`,
    ],
    [
      /^Link to "(.+)" copied to clipboard\.$/,
      ([, title]) =>
        language === 'om'
          ? `Hidhaan "${title}" gara kuushaatti garagalfame.`
          : language === 'am'
            ? `የ"${title}" አገናኝ ወደ ቅንጥብ ሰሌዳ ተቀድቷል።`
            : `تم نسخ رابط "${title}" إلى الحافظة.`,
    ],
    [
      /^Save reference (.+) for follow-up\.$/,
      ([, reference]) =>
        language === 'om'
          ? `Hordoffiif lakkoofsa wabii ${reference} olkaa’aa.`
          : language === 'am'
            ? `ለክትትል ማጣቀሻ ቁጥር ${reference} ያስቀምጡ።`
            : `احفظ الرقم المرجعي ${reference} للمتابعة.`,
    ],
    [
      /^Tracking #(.+) copied to clipboard$/,
      ([, code]) =>
        language === 'om'
          ? `Lakkoofsi hordoffii #${code} gara kuushaatti garagalfame`
          : language === 'am'
            ? `የመከታተያ ቁጥር #${code} ወደ ቅንጥብ ሰሌዳ ተቀድቷል`
            : `تم نسخ رقم التتبع #${code} إلى الحافظة`,
    ],
    [
      /^Found tracking record for (.+)$/,
      ([, name]) =>
        language === 'om'
          ? `Galmeen hordoffii ${name} argameera`
          : language === 'am'
            ? `የ${name} መከታተያ መዝገብ ተገኝቷል`
            : `تم العثور على سجل التتبع لـ ${name}`,
    ],
    [
      /^Review Case: (.+)$/,
      ([, reference]) =>
        language === 'om'
          ? `Dhimmicha sakatta’i: ${reference}`
          : language === 'am'
            ? `ጉዳዩን ይገምግሙ፡ ${reference}`
            : `مراجعة الحالة: ${reference}`,
    ],
    [
      /^Turn (.+) (off|on)$/,
      ([, serviceName, state]) =>
        language === 'om'
          ? `Tajaajila ${serviceName} ${state === 'off' ? 'cufi' : 'bani'}`
          : language === 'am'
            ? `የ${serviceName} አገልግሎት ${state === 'off' ? 'አጥፋ' : 'አብራ'}`
            : `${state === 'off' ? 'إيقاف' : 'تفعيل'} خدمة ${serviceName}`,
    ],
    [
      /^(Disable|Enable) (.+)$/,
      ([, action, serviceName]) =>
        language === 'om'
          ? `${serviceName} ${action === 'Disable' ? 'dhaabi' : 'bani'}`
          : language === 'am'
            ? `${serviceName} ${action === 'Disable' ? 'አቦዝን' : 'አንቃ'}`
            : `${action === 'Disable' ? 'تعطيل' : 'تفعيل'} ${serviceName}`,
    ],
    [
      /^Delete (.+)$/,
      ([, name]) =>
        language === 'om'
          ? `${name} haqi`
          : language === 'am'
            ? `${name} ሰርዝ`
            : `حذف ${name}`,
    ],
    [
      /^Edit (.+)$/,
      ([, name]) =>
        language === 'om'
          ? `${name} sirreessi`
          : language === 'am'
            ? `${name} አርም`
            : `تعديل ${name}`,
    ],
    [
      /^Update (.+) status$/,
      ([, reference]) =>
        language === 'om'
          ? `Haala ${reference} haaromsi`
          : language === 'am'
            ? `የ${reference} ሁኔታን አዘምን`
            : `تحديث حالة ${reference}`,
    ],
  ];

  for (const [pattern, render] of dynamicTemplates) {
    const match = source.match(pattern);
    if (match) return render(match);
  }
  return source;
};
